import"./chunk-2NFLSA4Y.js";var s={sound:{theory:{concept:"[[Sound is a mechanical wave \u2014 a travelling oscillation of pressure and density \u2014 in an elastic medium such as air, water or a solid; in air it is a longitudinal wave.]] It cannot travel through a vacuum. People hear frequencies from about 20 Hz to 20 000 Hz; lower frequencies are infrasound, higher ones ultrasound. The pitch of a sound is set by its frequency, and its loudness by the amplitude of the pressure oscillation, measured on the decibel scale. The speed of sound depends on the medium and its temperature \u2014 about 343 m/s in air at 20 \xB0C \u2014 so in one medium a higher pitch means a shorter wavelength, \u03BB = v / f."},section:{what:{title:"What sound is",text:"The cone of a loudspeaker moves back and forth hundreds of times per second. Each push makes a compression of air, each pull a rarefaction, and they travel away from the speaker. The lines in the picture are the compressions, drawn to scale (see the 1 m bar), but moving in slow motion. The air itself does not fly away: each bit of air only trembles by some tens of nanometres \u2014 about a hundred atoms side by side."},pitch:{title:"Pitch is frequency",text:"The more vibrations per second, the higher the note. A bass guitar's lowest string vibrates 41 times per second (41 Hz); a whistle can reach 4000 Hz. Watch the oscilloscope under the air: it shows the pressure at a microphone during 10 ms. At a higher frequency more waves fit into the same time and the compressions in the air come closer together: \u03BB = v / f."},notes:{title:"Notes and octaves",text:"Musicians tune to A4 = 440 Hz. Doubling the frequency gives the same note one octave higher (A5 = 880 Hz); halving it gives one octave lower (A3 = 220 Hz). An octave is split into 12 equal steps (semitones): each step multiplies the frequency by 2^(1/12) \u2248 1.059. Middle C (C4) is 261.6 Hz. A cent is one hundredth of a semitone; trained ears notice about 5 cents."},loudness:{title:"Loudness and decibels",text:"[[A loud sound has larger pressure swings, not a higher pitch.]] Our ears handle an enormous range, so loudness is measured on a logarithmic scale: every +20 dB means 10 times larger pressure swings, every +10 dB 10 times more power. 0 dB is the quietest sound people can hear (20 \xB5Pa), talking is about 60 dB, heavy traffic 85 dB, a rock concert 110 dB. Long exposure above 85 dB damages hearing. Loudness does not change the wavelength or the speed."},speed:{title:"The medium sets the speed",text:"[[In air at 20 \xB0C sound travels 343 m/s; in cold air it is slower (331 m/s at 0 \xB0C), in warm air faster.]] In water it travels about 1480 m/s and in steel about 5960 m/s, because they are much stiffer. The frequency stays the same when sound passes into another medium \u2014 the source sets it \u2014 so the wavelength grows: an A4 is 78 cm long in air but 3.4 m in water."},hearing:{title:"What we can hear",text:"Young people hear from about 20 Hz to 20 000 Hz; the upper limit drops with age. Below 20 Hz is infrasound (elephants, earthquakes, wind); above 20 000 Hz is ultrasound (bats, dolphins, medical scanners). In air, 20 Hz is a 17 m long wave and 20 000 Hz just 1.7 cm."},check:{title:"Check your understanding",text:"What happens to the wavelength in air if you double the frequency? (It halves.) Is 880 Hz the same note as 440 Hz? (Yes, one octave higher.) How many times larger are the pressure swings at 80 dB than at 60 dB? (10 times.) Why is the wavelength longer in water at the same frequency? (Sound is faster there.) Try each one in the simulation."}},formula:{speed:"Speed of sound: frequency times wavelength",period:"Period: the time of one vibration",octave:"One octave higher (f\u2082) is twice the frequency (f\u2081)",note:"Equal temperament: note n (A4 = 69, middle C = 60)",level:"Sound level from the (rms) pressure swing p",air:"Speed of sound in dry air at temperature t"},assumption:{pure:"A pure tone (a single sine wave). Real instruments add overtones, which give each one its own sound colour.",small:"An endless, still, dry medium: no echoes, no damping, and the level does not fall with distance. The wave is small enough to be linear.",slow:"The wave is drawn to scale but in enormous slow motion: each compression moves on by one wavelength per second. The frequency, wavelength and speed shown are the real ones.",scope:'The oscilloscope trace grows with the level in decibels, not in proportion to the pressure (that would range a million times). The "Listen" tone is kept quiet for safety, so it is not as loud as the level you set.'},param:{frequency:"Frequency (pitch)",level:"Sound level, dB",medium:"Medium",temperature:"Air temperature",timeStep:"Time step"},hint:{frequency:"How many compressions per second. A higher frequency sounds higher.",level:"How loud the sound is, in decibels. Every +20 dB makes the pressure swings 10 times larger.",medium:"What the sound travels through. Sound is fastest in solids.",temperature:"Sound travels faster in warm air."},preset:{infrasound:"10 Hz",a2:"A2",middleC:"C4",a4:"A4",a5:"A5",whistle:"Whistle",ultrasound:"25 kHz",whisper:"Whisper",talk:"Talking",traffic:"Traffic",concert:"Concert"},medium:{air:"Air",water:"Water",steel:"Steel"},measure:{wavelength:"Wavelength",period:"Period",level:"Sound level, dB",speed:"Speed of sound",cents:"Deviation from the nearest note, cents",pressure:"Pressure swing (peak)",displacement:"Displacement of the air (peak)",octaves:"Octaves above A4"},variable:{pressure:"Pressure swing (rms)"},graph:{wavelength:"Wavelength vs frequency"},view:{tooDense:"\u03BB is too short to draw",metre:"1 m",scope:"microphone, 10 ms: {periods} vibrations",note:"nearest note: {note} ({cents} \xA2)",infrasound:"infrasound: we cannot hear it",ultrasound:"ultrasound: we cannot hear it",listenOption:"Listen (play the tone)",frontsOption:"Compressions",scopeOption:"Oscilloscope",distancesOption:"Wavelength and scale"},challenge:{octave:{title:"One octave up",description:"Play the A one octave above A4 (440 Hz).",hint:"One octave higher means twice the frequency."},oneMetre:{title:"A one-metre wave",description:"In air at 20 \xB0C, set the frequency so that the wavelength is 1 m.",hint:"f = v / \u03BB, and sound in air travels about 343 m/s."},tooLow:{title:"Too low to hear",description:"Make a sound that people cannot hear because it is too low.",hint:"Our hearing starts at about 20 Hz."},middleC:{title:"Middle C",description:"Tune the tone to C4 (middle C) within 5 cents.",hint:"C4 is 9 semitones below A4: 440 Hz \xB7 2^(\u22129/12)."},water:{title:"Long waves in water",description:"In water, make a wave at least 3.5 m long with a frequency of 400 Hz or more.",hint:"Sound in water travels about 1480 m/s, so \u03BB = 1480 / f."},cold:{title:"Slow sound",description:"Make sound in air slower than 320 m/s.",hint:"Cold air carries sound more slowly."},pascal:{title:"One pascal",description:"Make the rms pressure swing reach 1 Pa (the peak swing is \u221A2 times larger).",hint:"p = 20 \xB5Pa \xB7 10^(L/20). How many decibels give 1 Pa?"}}}},a={sim:s};export{a as default,s as sim};
